//! Synapse-authored room-v11 vectors (no Docker, no network).
//!
//! `tests/fixtures/synapse_v11.json` is generated by
//! `tests/fixtures/gen_synapse_v11.py` with the pinned Synapse 1.162.0: every
//! hash, event ID, signature and signature-stage verdict in it was computed by
//! Synapse. These tests assert that Conduit's decode → content hash → derived
//! ID → signature checks reproduce Synapse's values and verdicts, and pin the
//! recorded divergences (explicit `event_id`, `outlier`, rule 4.2 on
//! non-join memberships).

use conduit::auth::check_authoriser_signature;
use conduit::hashing::{content_hash_matches, event_id};
use conduit::keys::{public_bytes, server_key_from_bytes};
use conduit::signing::{check_received, verify_signatures};
use conduit::wire::{decode_pdu, PduDecodeError};
use serde_json::Value;

fn fixture() -> Value {
    serde_json::from_str(include_str!("fixtures/synapse_v11.json")).unwrap()
}

fn lookup(fixture: &Value) -> impl Fn(&str, &str) -> Option<Vec<u8>> {
    let keys: Vec<(String, String, Vec<u8>)> = fixture["keys"]
        .as_object()
        .unwrap()
        .iter()
        .map(|(server, k)| {
            let key_id = k["key_id"].as_str().unwrap().to_owned();
            let seed = [k["seed_byte"].as_u64().unwrap() as u8; 32];
            let key = server_key_from_bytes(&key_id, &seed).unwrap();
            assert_eq!(
                base64_unpadded(&public_bytes(&key)),
                k["public"].as_str().unwrap(),
                "seed reproduces Synapse's public key"
            );
            (server.clone(), key_id, public_bytes(&key))
        })
        .collect();
    move |server, key_id| keys.iter().find(|(s, k, _)| s == server && k == key_id).map(|(_, _, p)| p.clone())
}

fn base64_unpadded(bytes: &[u8]) -> String {
    use base64::Engine as _;
    base64::engine::general_purpose::STANDARD_NO_PAD.encode(bytes)
}

#[test]
fn synapse_extended_pdu_decodes_hashes_and_verifies() {
    let f = fixture();
    let v = &f["extended"];
    let decoded = decode_pdu(v["pdu"].clone(), 0).unwrap();
    assert!(decoded.pdu.extensions.contains_key("org.example.extension"));
    assert!(content_hash_matches(&decoded.pdu).unwrap());
    assert_eq!(event_id(&decoded.pdu).unwrap(), v["event_id"].as_str().unwrap());
    // Re-serialising the decoded Pdu reproduces Synapse's object exactly.
    assert_eq!(serde_json::to_value(&decoded.pdu).unwrap(), v["pdu"]);
    let received = check_received(decoded.pdu, lookup(&f)).unwrap();
    assert!(!received.redacted_on_receipt);
    assert_eq!(received.event_id, v["event_id"].as_str().unwrap());
    assert_eq!(v["synapse_signature_stage"], "accepted");
}

#[test]
fn explicit_event_id_is_refused_by_both() {
    let f = fixture();
    let v = &f["explicit_event_id"];
    assert!(v["synapse"].as_str().unwrap().contains("must not have an explicit event_id"));
    assert_eq!(decode_pdu(v["pdu"].clone(), 0).unwrap_err(), PduDecodeError::ExplicitEventId);
}

#[test]
fn outlier_extension_pins_the_content_hash_divergence() {
    // Synapse's compute_content_hash pops `outlier`; the spec does not. The
    // same PDU therefore fails Conduit's content-hash check and is redacted
    // on receipt — under the identical, Synapse-computed event ID.
    let f = fixture();
    let v = &f["outlier"];
    let decoded = decode_pdu(v["pdu"].clone(), 0).unwrap();
    assert!(!content_hash_matches(&decoded.pdu).unwrap());
    let received = check_received(decoded.pdu, lookup(&f)).unwrap();
    assert!(received.redacted_on_receipt);
    assert_eq!(received.event_id, v["event_id"].as_str().unwrap());
    assert!(received.pdu.extensions.is_empty());
}

#[test]
fn restricted_join_verdicts_match_synapse() {
    let f = fixture();
    for v in f["restricted_join"].as_array().unwrap() {
        let pdu = decode_pdu(v["pdu"].clone(), 0).unwrap().pdu;
        let conduit = match verify_signatures(&pdu, lookup(&f)) {
            Ok(_) => "accepted".to_owned(),
            Err(_) => "dropped".to_owned(),
        };
        let synapse = v["synapse_signature_stage"].as_str().unwrap();
        assert!(synapse.starts_with(&conduit), "{}: conduit {conduit}, synapse {synapse}", v["name"]);
        assert_eq!(event_id(&pdu).unwrap(), v["event_id"].as_str().unwrap());
    }
}

#[test]
fn non_join_authoriser_is_a_rule_4_2_rejection_not_a_drop() {
    let f = fixture();
    for v in f["non_join_authoriser"].as_array().unwrap() {
        let name = v["name"].as_str().unwrap();
        let pdu = decode_pdu(v["pdu"].clone(), 0).unwrap().pdu;
        // Signature stage: never dropped, as in Synapse.
        let signed_by = verify_signatures(&pdu, lookup(&f)).unwrap_or_else(|e| panic!("{name}: {e}"));
        assert_eq!(v["synapse_signature_stage"], "accepted", "{name}");
        // Auth rule 4.2: only the validly co-signed variant passes.
        let auth = check_authoriser_signature(&pdu, &signed_by);
        assert_eq!(auth.is_ok(), name.ends_with("_valid"), "{name}");
    }
}

#[test]
fn third_party_invite_matches_synapse_exemption() {
    let f = fixture();
    let v = &f["third_party_invite"];
    let pdu = decode_pdu(v["pdu"].clone(), 0).unwrap().pdu;
    assert_eq!(v["synapse_signature_stage"], "accepted");
    verify_signatures(&pdu, lookup(&f)).unwrap();
}
